57	 * same combo twice. Any stride coprime with `n` visits all of it, so pick the
58	 * smallest one above 1 and fall back to 1 for n ≤ 2.
59	 */
60	function decorrelatedStride(n: number): number {
61	  for (let s = 2; s < n; s++) if (gcd(s, n) === 1) return s;
