75	 * stretch is deliberately one step, not unlimited — it lets sneakers into Work
76	 * but NOT into Evening [3.5, 5], and never lets an f=1 shoe into Work.
77	 */
78	function floorTolerance(category: string): number {
79	  return category === "Shoes" ? 1 : 0.5;
80	}
