136	 *    combo list, so in-season pieces must come first or a large off-season
137	 *    closet could push the good combos past the cap.
138	 * 2. Material RELIEF: a weather exclusion may narrow a REQUIRED slot but must
139	 *    never empty it. A closet whose only shoes are suede should get its suede
140	 *    shoes on a wet day, not an empty screen blaming "Shoes". Relief is scoped
141	 *    to weather exclusions — a formality gap is a real wardrobe gap and is still
142	 *    reported.
143	 */
144	export function eligibleByCategory(
145	  items: CandidateItem[],
146	  a: CandidateArgs,
147	): Record<string, CandidateItem[]> {
