185	  // Season ordering and material relief both live in `eligibleByCategory`, so
186	  // this function, `eligibility` and `missingCategory` can never disagree about
187	  // what the closet can do. Ordering in-season-first matters because the CAP
188	  // below truncates the combo list, and the breadth-first walk indexes outerwear
189	  // and accessories modulo their list length — so the earliest passes reach the
190	  // seasonally right coat and accessory.
191	  const by = eligibleByCategory(items, a);
192	  const tops = by.Tops ?? [];
193	  const bottoms = by.Bottoms ?? [];
194	  const shoes = by.Shoes ?? [];
195	  const outer = by.Outerwear ?? [];
196	  const accessories = by.Accessories ?? [];
197	
198	  // A combo needs all three required slots; without one there is nothing to build.
199	  if (!tops.length || !bottoms.length || !shoes.length) return [];
200	
201	  const combos: CandidateItem[][] = [];
202	
203	  // BREADTH-FIRST, not a nested product.
204	  //
205	  // This used to be three nested loops followed by `.slice(0, CAP)`. Because the
206	  // loops were top-major, every combination of the FIRST top was generated
207	  // before the second top was reached — so the cap was spent inside one top. A
208	  // closet with 20 of each category reached 1 top and 5 bottoms out of 20, which
209	  // is both reported symptoms at once: most of the wardrobe invisible to
210	  // ranking, and every look sharing a garment because there was only one to
211	  // share. Small closets stayed under the cap, which is why tests never saw it.
212	  //
213	  // Each pass `d` walks all tops once, pairing each with a different bottom and
214	  // shoe, so pass 0 alone touches every top, bottom and shoe. Later passes add
215	  // fresh pairings rather than exhausting one corner of the space. The shoe
216	  // offset uses a stride coprime with the shoe count so pairings do not repeat
217	  // early AND every shoe is still reachable — a fixed stride of 2 failed the
218	  // second half of that on any even-length list (see `decorrelatedStride`).
219	  const passes = Math.max(bottoms.length, shoes.length);
220	  const shoeStride = decorrelatedStride(shoes.length);
221	
222	  build: for (let d = 0; d < passes; d++) {
223	    for (let t = 0; t < tops.length; t++) {
224	      const b = bottoms[(t + d) % bottoms.length];
225	      const s = shoes[(t + d * shoeStride) % shoes.length];
226	
227	      // Outerwear is a PREFERENCE, not a requirement: layer it in when the cold
228	      // calls for it and the closet has one, but never refuse to dress someone
229	      // who owns no coat — that silently killed every outfit below 15°.
230	      // The weather strip's "Later" advice is what tells them to take a layer.
231	      // The index rotates too: it was pinned to [0], so one coat was worn on
232	      // every cold day and every other coat was unreachable.
233	      const base =
234	        needsOuterwear && outer.length
235	          ? [tops[t], b, s, outer[(t + d) % outer.length]]
236	          : [tops[t], b, s];
237	
238	      combos.push(base); // required base (± outerwear), no accessory
239	      if (combos.length >= CAP) break build;
240	
241	      if (a.maxAccessories > 0 && accessories.length) {
242	        combos.push([...base, accessories[(t + d) % accessories.length]]); // optional, capped accent
243	        if (combos.length >= CAP) break build;
244	      }
245	    }
246	  }
247	
248	  // Colour is deliberately NOT filtered here. The Refine palette is a lean, and
249	  // leans are expressed by ranking (`scoreCombo`'s lean term), not by exclusion —
250	  // the same soft-preference model outerwear moved to above.
251	  return combos;
252	}
